sys_script_client.script:
function onSubmit() {
    var password = g_form.getValue('password');
    var confirmPassword = g_form.getValue('confirm_password');
	var email=g_form.getValue("email");
	if(!(email.endsWith("@gmail.com")))
	{
		g_form.showFieldMsg("email","Enter correct mail","error");
		return false;
	}


    if (password.length < 8) {
        g_form.showFieldMsg('password', 'Password must be at least 8 characters long.', 'error');
        return false;
    }


    if (!/[A-Z]/.test(password)) {
        g_form.showFieldMsg('password', 'Password must contain at least one uppercase letter.', 'error');
        return false;
    }


    if (!/[a-z]/.test(password)) {
        g_form.showFieldMsg('password', 'Password must contain at least one lowercase letter.', 'error');
        return false;
    }


    if (!/[0-9]/.test(password)) {
        g_form.showFieldMsg('password', 'Password must contain at least one number.', 'error');
        return false;
    }


    if (!/[!@#\$%\^\&*\)\(+=._-]/.test(password)) {
        g_form.showFieldMsg('password', 'Password must contain at least one special character.', 'error');
        return false;
    }


    if (password !== confirmPassword) {
        g_form.showFieldMsg('confirm_password', 'Passwords do not match.', 'error');
        return false;
    }


    return true; 
}
